def transform(grid):
    """Mark tiles containing at least two non-background marks in one column."""
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, seps):
        result, start = [], 0
        for i in seps:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    out = []
    for r0, r1 in row_spans:
        out_row = []
        for c0, c1 in col_spans:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            background = Counter(vals).most_common(1)[0][0]
            marked_cols = Counter(
                c - c0
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != background
            )
            out_row.append(int(any(count >= 2 for count in marked_cols.values())))
        out.append(out_row)
    return out
